// ui_screen.js

const STATE = require('STATE')
const statedb = STATE(__filename)
const { get } = statedb(fallback_module)
const net = require('net_helper')

const ui_card = require('ui_card')

module.exports = ui_screen

async function ui_screen (opts, invite) {
  const { id, sdb } = await get(opts.sid)
  const { drive } = sdb

  const on = {
    style: inject
  }

  const { io, _ } = net(id)

  io.on = {
    up: (msg) => {
      console.log('ui_screen:', msg.type)
    }
  }

  if (invite) io.accept(invite)

  const el = document.createElement('div')
  const shadow = el.attachShadow({ mode: 'closed' })

  shadow.innerHTML = `
    <div class="ui-screen-canvas">
      <div class="grid-layer">
        <div class="card-slot"></div>

        <!--
        <div class="card-slot"></div>
        <div class="card-slot"></div>
        <div class="card-slot"></div>
        <div class="card-slot"></div>
        <div class="card-slot"></div>
        -->
      </div>

      <div class="bottom-bar"></div>
    </div>
  `

  const sheet = new CSSStyleSheet()
  shadow.adoptedStyleSheets = [sheet]

  const slots = shadow.querySelectorAll('.card-slot')

  const subs = await sdb.watch(onbatch)

  // -----------------------------------
  // single card for now
  // -----------------------------------

  const card = await ui_card({
    ...subs[0],
    ids: { up: id }
  })

  card.classList.add('ui-card-instance')

  slots[0].replaceWith(card)

  // -----------------------------------
  // Multiple UI Card 
  // -----------------------------------

  /*
  for (const slot of slots) {
    const card = await ui_card({
      ...subs[0],
      ids: { up: id }
    })

    card.classList.add('ui-card-instance')
    slot.replaceWith(card)
  }
  */

  return el

  // -----------------------------------
  // batch handler
  // -----------------------------------

  async function onbatch (batch) {
    for (const { type, paths } of batch) {
      const data = await Promise.all(
        paths.map(load_path_raw)
      )

      const handler = on[type] || fail
      handler({ data, type })
    }

    function load_path_raw (path) {
      return drive.get(path).then(read_drive_file_raw)
    }

    function read_drive_file_raw (file) {
      return file.raw
    }
  }

  function inject ({ data }) {
    sheet.replaceSync(data[0])
  }

  function fail ({ type, data }) {
    console.warn('ui_screen: unknown batch type', type, data)
  }
}

function fallback_module () {
  return {
    api: fallback_instance,

    _: {
      ui_card: { $: '' },
      net_helper: { $: '' }
    }
  }

  function fallback_instance () {
    return {
      _: {
        ui_card: {
          0: '',
          mapping: {
            style: 'style'
          }
        },

        net_helper: {
          0: ''
        }
      },

      drive: {
        'style/ui_screen.css': {
          raw: `
            :host {
              display: block;
              width: 100%;
              max-width: 100%;
              aspect-ratio: 16 / 7;
              overflow: hidden;
              box-sizing: border-box;
            }

            * {
              box-sizing: border-box;
            }

            .ui-screen-canvas {
              width: 100%;
              height: 100%;
              display: flex;
              flex-direction: column;
              background: #060606;
              border-radius: 10px;
              overflow: hidden;
            }

            .grid-layer {
              flex: 1;
              display: grid;
              grid-template-columns: repeat(3, 1fr);
              grid-template-rows: repeat(2, 1fr);
              gap: 18px;
              padding: 18px;
              min-height: 0;
            }

            .ui-card-instance {
              width: 100%;
              height: 100%;
              min-width: 0;
              min-height: 0;
            }

            .bottom-bar {
              width: 100%;
              height: 56px;
              background: #111111;
              border-top: 1px solid rgba(255,255,255,0.04);
              flex-shrink: 0;
            }

            @media (max-width: 900px) {
              .grid-layer {
                gap: 12px;
                padding: 12px;
              }

              .bottom-bar {
                height: 48px;
              }
            }
          `
        }
      }
    }
  }
}